CREATE TYPE "AppointmentStatus" AS ENUM ('PENDING','CONFIRMED','CALLING','COMPLETED','CANCELLED');
ALTER TABLE "LiveRoom" ADD COLUMN "publishUrl" TEXT, ADD COLUMN "playbackUrl" TEXT NOT NULL DEFAULT '';
CREATE TABLE "LiveInvite" ("id" TEXT NOT NULL,"roomId" TEXT NOT NULL,"code" TEXT NOT NULL,"type" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LiveInvite_pkey" PRIMARY KEY("id"));
CREATE TABLE "Appointment" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"anchorId" TEXT NOT NULL,"scheduledAt" TIMESTAMP(3) NOT NULL,"note" TEXT,"status" "AppointmentStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Appointment_pkey" PRIMARY KEY("id"));
CREATE TABLE "ChatSetting" ("userId" TEXT NOT NULL,"allowMessages" BOOLEAN NOT NULL DEFAULT true,"greeting" TEXT NOT NULL DEFAULT '',CONSTRAINT "ChatSetting_pkey" PRIMARY KEY("userId"));
CREATE UNIQUE INDEX "LiveInvite_code_key" ON "LiveInvite"("code");
ALTER TABLE "LiveInvite" ADD CONSTRAINT "LiveInvite_roomId_fkey" FOREIGN KEY("roomId") REFERENCES "LiveRoom"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_anchorId_fkey" FOREIGN KEY("anchorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChatSetting" ADD CONSTRAINT "ChatSetting_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
